  'explore-markets':()=>document.getElementById('market-explore')?.scrollIntoView({behavior:'smooth',block:'start'}),
  top:()=>document.getElementById('main')?.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}),
  theme:()=>{if(S.overlay==='theme')closeOverlay();else themeMenu()},
  'set-theme':v=>{S.themeMode=v;S.theme=ForeaTheme.save(v);closeOverlay();render({preserve:true})},
  language:()=>{if(S.overlay==='language')closeOverlay();else languageMenu()},
  'set-language':v=>{if(!['zh','en'].includes(v))return;S.lang=v;localStorage.setItem('forecast-design-lang',v);render({preserve:true});languageMenu();window.languageCloseTimer=setTimeout(()=>{if(S.overlay==='language')closeOverlay()},2000)},
  'agent-tab':v=>{S.agentTab=Number(v);const sub=['','/analysis','/execution','/monitoring'][S.agentTab];history.replaceState(null,'','#agent'+sub);render({preserve:true})},
  'liquidity-tab':v=>{S.liquidityTab=Number(v);history.replaceState(null,'','#liquidity'+(S.liquidityTab?'/services':''));render({preserve:true})},
  'monitor-tab':v=>{S.monitorTab=v;render({preserve:true})},
  'agent-max':()=>{S.amount=Math.min(1000,S.walletBalance);render({preserve:true})},
  'agent-primary':()=>{Tokenomics.ensure();if(S.agentState==='inactive')return startReview();if(['cancelling','stopped'].includes(S.agentState)&&S.tokenProjectBalance<1)return requestTokenFunding();if(S.agentState==='cancelling'){consumeDemoToken(false);S.agentState='resuming';S.elapsed=0;S.startedAt=Date.now();render({preserve:true});toast(U.t('正在恢复运行','Resuming execution'));}else if(S.agentState==='stopped'){consumeDemoToken();S.agentState='running';S.elapsed=0;S.startedAt=Date.now();render({preserve:true});toast(U.t('已开始新周期','New cycle started'))}},
  'start-demo':()=>{const n=Number(S.amount);if(S.overlay!=='agent-start'||!Number.isFinite(n)||n<20||n>1000||n>S.walletBalance)return;if(S.tokenProjectBalance<1){const input=document.getElementById('agent-token-topup'),need=Number((1-S.tokenProjectBalance).toFixed(8)),k=Number(input?.value);if(!input||!Number.isFinite(k)||k<need||k>S.tokenWalletBalance){const e=document.getElementById('agent-token-error');if(e)e.textContent=U.t(`请输入 ${U.money(need)}–${U.money(S.tokenWalletBalance)} MAAT`,`Enter ${U.money(need)}–${U.money(S.tokenWalletBalance)} MAAT`);return}if(!Tokenomics.depositToProject(k))return}consumeDemoToken();S.capital=n;S.walletBalance-=n;U.record('agent-start',-n);S.agentState='running';S.elapsed=0;S.startedAt=Date.now();const custody=S.runMode==='custody';if(custody)startCustody();closeOverlay();render();toast(custody?U.t('已开启托管','Custody started'):U.t('已开始运行','Run started'))},
  'run-mode':v=>{if(S.overlay!=='agent-start'||!['cycle','custody'].includes(v))return;S.runMode=v;startReview();document.querySelector(`[data-action="run-mode"][data-value="${v}"]`)?.focus()},
  'custody-review':()=>{if(S.agentState!=='running'||S.custody||!S.capital)return;const {t}=U,pct=Math.round(U.custody.rate*100);sheet(t('开启托管','Start custody'),`<p>${t('托管期间 Agent 自动连续运行，无需每 8 小时确认','The Agent runs continuously, with no check-in every 8H')}</p><div style="margin-top:20px">${[[t('本金','Principal'),U.money(S.capital)+' USDC'],[t('托管期限','Custody term'),t(`最长 ${U.custody.days} 天`,`Up to ${U.custody.days} days`)],[t(`托管费（本金 ${pct}%）`,`Custody fee (${pct}% of principal)`),`<span data-row="custody-fee">−${U.money(S.capital*U.custody.rate)} USDC</span>`],[t('停止托管','Stop custody'),t(`满 ${U.custody.minHours} 小时后可停止`,`After ${U.custody.minHours}H`)],[t('到期或停止后','When it ends'),t('进入撤单 3–5H','Exit phase 3–5H')]].map(([a,b])=>`<div class="confirm-row"><span>${a}</span><b>${b}</b></div>`).join('')}</div><p class="tiny muted confirm-note">${t('托管费开启时从 Agent 账户扣除，提前停止不退','The fee is taken from the Agent account when custody starts and is not refunded on an early stop')}</p><div class="confirm-actions"><button class="btn secondary" data-action="close">${t('取消','Cancel')}</button><button class="btn primary" data-action="confirm-custody">${t('开启托管','Start custody')}</button></div>`,'sheet','custody-review')},
  'confirm-custody':()=>{if(S.overlay!=='custody-review'||S.agentState!=='running'||S.custody||!S.capital)return;startCustody();closeOverlay();render({preserve:true});toast(U.t('已开启托管','Custody started'))},
  'custody-stop':()=>{const c=U.custodyInfo(),{t}=U;if(!c||!c.canStop||S.agentState!=='running')return;sheet(t('停止托管','Stop custody'),`<p>${t('停止后进入撤单 3–5 小时，完成后可提出','The Agent enters the 3–5H exit phase, then you can withdraw')}</p><div style="margin-top:20px">${[[t('托管剩余','Custody left'),c.time],[t('托管费','Custody fee'),t(`已扣 ${U.money(S.custodyFee)} USDC，不退`,`${U.money(S.custodyFee)} USDC paid, not refunded`)]].map(([a,b])=>`<div class="confirm-row"><span>${a}</span><b>${b}</b></div>`).join('')}</div><div class="confirm-actions"><button class="btn secondary" data-action="close">${t('继续托管','Keep custody')}</button><button class="btn primary" data-action="confirm-custody-stop">${t('确认停止','Stop now')}</button></div>`,'sheet','custody-stop')},
  'confirm-custody-stop':()=>{const c=U.custodyInfo();if(S.overlay!=='custody-stop'||!c?.canStop||S.agentState!=='running')return;endCustody();closeOverlay();render({preserve:true});toast(U.t('已停止托管，进入撤单','Custody stopped. Exit phase started'))},
  withdraw:()=>{if(S.agentState!=='stopped'||!S.capital)return;const p=U.performance(),pct=Math.round(U.custody.rate*100);sheet(U.t('提出资金','Withdraw funds'),`<div class="confirm-row" style="margin-top:18px"><span>${U.t('本金','Principal')}</span><b>${U.money(S.capital)} USDC</b></div><div class="confirm-row"><span>${U.t('本周期盈亏','Cycle P&L')}</span><b>${p.gross>=0?'+':''}${U.money(p.gross)} USDC</b></div>${p.custodyFee?`<div class="confirm-row" data-row="custody"><span>${U.t(`托管费（本金 ${pct}%，已扣）`,`Custody fee (${pct}% of principal, paid)`)}</span><b>−${U.money(p.custodyFee)} USDC</b></div>`:''}<div class="confirm-row"><span>${U.t('返回金额','Amount')}</span><b data-row="cash">${U.money(p.cashBalance)} USDC</b></div><div class="confirm-row"><span>${U.t('到账账户','To account')}</span><b>${U.address()}</b></div><div class="confirm-actions"><button class="btn secondary" data-action="close">${U.t('取消','Cancel')}</button><button class="btn primary" data-action="confirm-withdraw">${U.t('确认提出','Confirm withdrawal')}</button></div>`)},
  'confirm-withdraw':()=>{if(S.agentState!=='stopped'||!S.capital)return;U.record('agent-withdraw',U.performance().cashBalance);S.walletBalance+=U.performance().cashBalance;S.capital=0;S.custodyFee=0;S.custody=null;S.agentState='inactive';S.elapsed=0;closeOverlay();render();toast(U.t('已返回钱包','Returned to your wallet'))},
  scene,
  disconnect:()=>OKXIdentity.disconnect(),
